-- Independent snapshots: removing a source draft must not remove a saved template.
CREATE TABLE personal_workout_templates (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    source_program_id integer REFERENCES personal_standalone_workouts(program_id) ON DELETE SET NULL,
    program jsonb NOT NULL CHECK (jsonb_typeof(program) = 'object'),
    favorite boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, source_program_id)
);
CREATE INDEX idx_personal_workout_template_owner ON personal_workout_templates(user_id, favorite DESC, created_at DESC, id DESC);
CREATE INDEX idx_personal_workout_template_source ON personal_workout_templates(source_program_id);
